ic", "title": "Editing Tools, Automation, and Responsible AI", "description": "Editing tools can improve speed and consistency, but editors remain accountable for judgment. This unit teaches students to use automation critically.", "children": [{"id": "6524c711-68da-46bd-99ae-7f50bae01578", "type": "subtopic", "title": "Digital editing tools", "children": [{"id": "cd11c1bf-48fc-41f9-9518-bda9007003d5", "type": "concept", "title": "style checkers"}, {"id": "4a7270f0-8dc4-475f-bb88-13683e92ea81", "type": "concept", "title": "collaborative docs"}, {"id": "29a9e18b-6e85-49e4-9472-6a4995142e1d", "type": "concept", "title": "CMS validators"}], "description": "Students compare grammar checkers, style linters, collaborative editing tools, CMS checks, and newsroom templates."}, {"id": "9abe066a-77dc-4c4b-9051-6dddf2168f73", "type": "subtopic", "title": "AI-assisted editing boundaries", "children": [{"id": "0fbd59d7-55ec-41fc-83ec-12fbb4c5d454", "type": "concept", "title": "hallucination checks"}, {"id": "c5a4222f-ad52-4747-80bb-8e7b59118895", "type": "concept", "title": "confidentiality"}, {"id": "14973b36-5647-48e7-9c04-c85998903ea3", "type": "concept", "title": "human approval"}], "description": "The class examines where AI may help with drafts, summaries, consistency checks, and headline variants, and where it can introduce risk."}, {"id": "bdbe2285-9f20-49de-a6a5-e89ae22a3f7c", "type": "subtopic", "title": "Bias and accountability in automation", "children": [{"id": "4e6d4684-9b91-4b20-b3f0-2f262d7a9c7a", "type": "concept", "title": "bias review"}, {"id": "1e13859a-1dd3-42c2-9951-d82df295036f", "type": "concept", "title": "meaning preservation"}, {"id": "567b52d3-97d8-4ea6-b82f-5c6c4b4bb82c", "type": "concept", "title": "audit trails"}], "description": "Students learn to question automated suggestions that flatten voice, change meaning, or encode bias."}, {"id": "08aa0050-5a6b-4a1d-a621-3951fa3860c6", "type": "subtopic", "title": "Tool policies and disclosure", "children": [{"id": "2b0197a3-9247-490d-988b-9b0f218438f1", "type": "concept", "title": "policy language"}, {"id": "4c03c042-0f5a-479f-84c5-314600ca6306", "type": "concept", "title": "data security"}, {"id": "a1e980fc-e220-4c2c-9b3e-a55a5bca4f56", "type": "concept", "title": "approval workflows"}], "description": "Editors draft newsroom rules for tool use, source protection, verification, and disclosure."}]}, {"id": "ce7edf8a-dbd1-4e84-868e-6ec14b6a4fad", "type": "topic", "title": "Capstone Copy Desk Simulation", "description": "The capstone turns the course into a working desk. Students edit a complete story package under deadline and defend their decisions.", "children": [{"id": "bacb9eae-09f0-4383-b0bd-1ff54dec1e29", "type": "subtopic", "title": "Editing a live-style story package", "children": [{"id": "76a11ab6-20bb-4fd8-8d13-483dfb36ad05", "type": "concept", "title": "story package checklist"}, {"id": "539c15af-4630-404a-bf00-06af426e6d30", "type": "concept", "title": "desk workflow"}, {"id": "b9a55c44-85ae-40d2-9be2-866d50f15e81", "type": "concept", "title": "final proof"}], "description": "Students handle text, headlines, captions, metadata, links, visual elements, and publication checks as one coherent package."}, {"id": "79f17894-8010-42a3-be48-d9b4cf314e68", "type": "subtopic", "title": "Standards memo and edit rationale", "children": [{"id": "a8e5b421-5efa-472c-b33c-4588e216ddc6", "type": "concept", "title": "edit memo"}, {"id": "2b6ec23c-28c1-4c94-a301-a252fc74dc7c", "type": "concept", "title": "risk notes"}, {"id": "74e18284-209f-4d37-85df-3a06fc655ab3", "type": "concept", "title": "source questions"}], "description": "Students explain major edits, unresolved risks, verification steps, and publication recommendations."}, {"id": "f4659e5b-ab61-4db9-9803-e85ac89c63b1", "type": "subtopic", "title": "Peer desk review", "children": [{"id": "0932ac4c-40db-45d5-99c9-cd47b8353926", "type": "concept", "title": "second reads"}, {"id": "4aa19fde-d413-4ba0-9590-c49dbbf2c4fa", "type": "concept", "title": "quality rubric"}, {"id": "5c50aac4-9fdc-4acd-8829-0cbf7bfbf5d8", "type": "concept", "title": "reader impact"}], "description": "The class uses structured peer review to test whether edits improved accuracy, clarity, fairness, and usability."}, {"id": "e7ffe5a9-408e-4a35-8465-a292ca952c92", "type": "subtopic", "title": "Portfolio reflection", "children": [{"id": "a826fa4f-a4c6-4c81-8c02-270faf2acd49", "type": "concept", "title": "before/after samples"}, {"id": "0db80075-ef45-4cf6-87a7-0fd05d1cc43d", "type": "concept", "title": "self-assessment"}, {"id": "df3ac9c3-a320-46dd-9e1b-2ae286321dea", "type": "concept", "title": "professional portfolio"}], "description": "Students assemble before-and-after edits showing growth in judgment, craft, collaboration, and standards."}]}], "dbBacked": true}$edcojson$::jsonb,
