set
  title = 'Editing and Copyediting',
  goal = 'Editing and Copyediting',
  summary = 'This course prepares undergraduate journalism students to work as careful, ethical, collaborative editors across print, digital, multimedia, and emerging newsroom environments. Students move from sentence-level copyediting to package-level editorial judgment, always connecting craft decisions to accuracy, fairness, reader trust, and public service.',
  data = $edcojson${"slug": "editing-and-copyediting", "title": "Editing and Copyediting", "description": "This course prepares undergraduate journalism students to work as careful, ethical, collaborative editors across print, digital, multimedia, and emerging newsroom environments. Students move from sentence-level copyediting to package-level editorial judgment, always connecting craft decisions to accuracy, fairness, reader trust, and public service.", "topics": [{"id": "c82c2ad6-a588-4f1e-ba71-0eaa88b5f455", "type": "topic", "title": "The Editing Process and Editorial Judgment", "description": "This opening unit frames editing as a disciplined act of judgment: protecting the reader, strengthening the story, and improving the work without erasing the reporter's voice.", "children": [{"id": "8386f146-fb9c-49e1-a23d-41a128d6b4bf", "type": "subtopic", "title": "The editor's role in a newsroom", "children": [{"id": "18241725-1ef0-422e-9c16-dbce6149e754", "type": "concept", "title": "editorial desk roles"}, {"id": "9043bbf4-3aed-492f-bbaf-162f12ca3f6a", "type": "concept", "title": "chain of review"}, {"id": "47871e83-8688-4772-bab4-f5e462c0480b", "type": "concept", "title": "reader-first decision-making"}], "description": "Students learn how assignment editors, copy editors, line editors, section editors, standards editors, and audience editors divide responsibility across a publication workflow."}, {"id": "288af56e-623d-4f82-aa5d-fc20cc152734", "type": "subtopic", "title": "Levels of editing", "children": [{"id": "0c51433b-199d-42b3-a3e9-e60fce76bd25", "type": "concept", "title": "substantive edits"}, {"id": "261b25ed-daaf-47d5-b20b-6043acf722e1", "type": "concept", "title": "sentence-level edits"}, {"id": "b744e2f7-6233-4a80-8c9a-ade421688284", "type": "concept", "title": "proofing versus rewriting"}], "description": "Students distinguish developmental editing, line editing, copyediting, proofreading, production editing, and final quality control so they can choose the right intervention."}, {"id": "1e79611e-a669-4c52-b0af-5b4cbb898f73", "type": "subtopic", "title": "Editorial judgment and news value", "children": [{"id": "126ddb10-2952-4a03-bd47-464764ea5c18", "type": "concept", "title": "newsworthiness"}, {"id": "f458c01a-ae03-499a-9e70-6416d12ed2e8", "type": "concept", "title": "angle and focus"}, {"id": "1ca04cc4-d8fd-4eb1-8d9a-7745915b0a5a", "type": "concept", "title": "proportionality"}], "description": "The unit introduces the judgment calls editors make about relevance, proportionality, public interest, tone, and what the reader needs next."}, {"id": "01f8d76c-58f9-44b0-a097-86177464b5e6", "type": "subtopic", "title": "Editing workflow and version control", "children": [{"id": "1bd48549-0cda-4541-8962-fa45bf165773", "type": "concept", "title": "edit logs"}, {"id": "8ec18d13-bfc4-4c96-8f97-ec79e4971f1d", "type": "concept", "title": "track changes"}, {"id": "14e3b97b-59f9-4089-ae82-f6921773319f", "type": "concept", "title": "slugging and file naming"}], "description": "Students practice moving a story from draft to publication while preserving accountability for changes."}]}, {"id": "f37cccd2-ed58-433e-9730-5af3b286a481", "type": "topic", "title": "Copyediting for Grammar, Usage, and Style", "description": "Copyediting builds the precision habits that make journalism readable and credible: clean grammar, consistent style, and decisions that serve meaning rather than pedantry.", "children": [{"id": "f7d61d3b-8aca-49f0-bd65-d5f513ae6c88", "type": "subtopic", "title": "Grammar for journalism", "children": [{"id": "2b03ef1b-47fc-4f13-94e7-5f2c63e77237", "type": "concept", "title": "subjects and verbs"}, {"id": "6e71293b-68cc-438f-9353-9e3496ad5c1a", "type": "concept", "title": "modifiers"}, {"id": "72a25567-fd82-4cae-8815-4b289d92ccbd", "type": "concept", "title": "pronoun reference"}], "description": "Students review the grammar problems that most often create ambiguity, legal risk, or reader confusion in news copy."}, {"id": "7138c22e-1f62-4b75-a5e6-9f079f22736d", "type": "subtopic", "title": "Punctuation and mechanics", "children": [{"id": "8928ee0b-5b2b-4325-99f9-efa163b23eaa", "type": "concept", "title": "commas"}, {"id": "ba5be9b8-5c5a-4ab0-a891-0617f1db9a89", "type": "concept", "title": "quotation marks"}, {"id": "ea496f63-f2ff-4457-a585-14f48a5b5623", "type": "concept", "title": "hyphens and dashes"}], "description": "The class practices punctuation as a tool for pacing, sense, quotation accuracy, and visual clarity."}, {"id": "b559304e-897e-4de9-93a1-1adb0aabda9a", "type": "subtopic", "title": "AP style and house style", "children": [{"id": "4ae1192c-50a1-403b-82b7-e6ece3f59d66", "type": "concept", "title": "capitalization"}, {"id": "fef5955a-c5ec-457b-873b-2e17d0b6f4af", "type": "concept", "title": "numbers"}, {"id": "6e58ed67-f93c-4611-892b-9e280f1cef68", "type": "concept", "title": "titles and identifiers"}], "description": "Students learn how to apply AP style, document exceptions, and reconcile a publication's house guide with broader newsroom norms."}, {"id": "7ee9c263-e8c1-4fc5-af55-e6aed253c592", "type": "subtopic", "title": "Consistency editing", "children": [{"id": "f24e3f89-4889-4570-962c-3d21f0205a86", "type": "concept", "title": "style sheets"}, {"id": "0bb8334e-36c4-46c0-bda6-2a52d3c560ee", "type": "concept", "title": "proper nouns"}, {"id": "7a4d9e50-6910-41a3-a92e-21d693acdcf0", "type": "concept", "title": "internal consistency"}], "description": "Students track repeated names, dates, spellings, terminology, captions, headlines, and references across a package."}]}, {"id": "e56abc62-5c9f-4f8a-8fda-77be8ec3c357", "type": "topic", "title": "Editing for Accuracy and Verification", "description": "Accuracy is the editor's non-negotiable duty. This unit turns fact-checking from a vague ideal into a repeatable verification process.", "children": [{"id": "9ed17124-0b3d-42c0-961b-ce0e59fc1183", "type": "subtopic", "title": "Fact-checking systems", "children": [{"id": "2cba637b-00ea-4f53-8bb7-c0d1fe102e63", "type": "concept", "title": "source triangulation"}, {"id": "657443cc-2bdf-4d50-985b-2e07c67fcf1a", "type": "concept", "title": "primary documents"}, {"id": "829d7764-6306-47d1-858e-e27118c22a26", "type": "concept", "title": "verification checklists"}], "description": "Students build checklists for names, dates, places, titles, numbers, links, quotes, and claims before publication."}, {"id": "8c2ca2bb-836c-4059-b5fb-fe8287e97953", "type": "subtopic", "title": "Numeracy and data accuracy", "children": [{"id": "e4b7b4ca-ee28-4b72-812a-742c0e53f298", "type": "concept", "title": "percent change"}, {"id": "459a5892-d41b-424f-8c65-3d7d2262c334", "type": "concept", "title": "base rates"}, {"id": "541fc46b-2626-4f40-a684-8a9d25f5dd4c", "type": "concept", "title": "chart labels"}], "description": "Editors learn to catch common errors in percentages, rankings, averages, rates, polls, budgets, and data visualizations."}, {"id": "525de853-6a61-4138-97bb-3085a8892392", "type": "subtopic", "title": "Quote and attribution checks", "children": [{"id": "63dc4b18-f4ca-401b-b2ff-6c5d3dbe4752", "type": "concept", "title": "quote context"}, {"id": "37c5ae27-2133-452e-a966-840fc24b0658", "type": "concept", "title": "on/off background"}, {"id": "7a72db81-9e22-4130-a90f-393cf91110ed", "type": "concept", "title": "source roles"}], "description": "Students verify quoted language, paraphrase accuracy, speaker identity, and the strength of attribution."}, {"id": "1ab7590e-1ad6-4d98-af86-ea5f0b5ea47b", "type": "subtopic", "title": "Corrections and transparency", "children": [{"id": "0672db1a-9712-4d9a-9881-6e913e846275", "type": "concept", "title": "correction language"}, {"id": "8ab7380b-660c-41f6-86e4-f96696a748cf", "type": "concept", "title": "updates"}, {"id": "2ed39aab-8657-450a-bd09-d52e809f88b4", "type": "concept", "title": "editor's notes"}], "description": "The unit covers how to respond when something is wrong after publication without compounding the error."}]}, {"id": "b7b54da0-d491-47f7-807f-c3a8ef30db30", "type": "topic", "title": "Editing for Clarity, Concision, and Voice", "description": "This unit teaches students to make stories sharper without flattening them. The goal is prose that moves quickly, says exactly what it means, and still sounds human.", "children": [{"id": "8d3e5c8d-15dd-4e52-b3bd-91565b58357b", "type": "subtopic", "title": "Sentence diagnosis", "children": [{"id": "b3dbe56d-9ad2-41e2-903f-692c47683721", "type": "concept", "title": "active verbs"}, {"id": "328d07a8-350a-48fc-ab77-9dc2634ff108", "type": "concept", "title": "sentence focus"}, {"id": "26fda196-4c97-4a09-af22-d59a0c563ea0", "type": "concept", "title": "clutter removal"}], "description": "Students learn to identify buried verbs, stacked clauses, vague subjects, inflated diction, and unnecessary throat-clearing."}, {"id": "38a512b4-57db-46af-929a-41382699f219", "type": "subtopic", "title": "Concision without loss", "children": [{"id": "dd30bc10-4324-4f91-88b5-631edca5c104", "type": "concept", "title": "word economy"}, {"id": "4e39ca8f-d00b-47e2-8ae1-16a3cbd5ba9f", "type": "concept", "title": "redundancy"}, {"id": "d814e0d7-f475-456a-b2bd-b3e8a738f5da", "type": "concept", "title": "compression"}], "description": "Editors practice cutting repetition, empty qualifiers, and needless background while preserving nuance and evidence."}, {"id": "aac2e328-2ef1-435c-ad07-bfd8dafbe80f", "type": "subtopic", "title": "Plain language and accessibility", "children": [{"id": "7d75a80f-5e13-4f64-894b-443471c20fe9", "type": "concept", "title": "jargon control"}, {"id": "23a46220-626d-45c0-b9b7-e5ddf3c13673", "type": "concept", "title": "definitions in context"}, {"id": "0d227856-38a6-4871-a8ea-676552b25928", "type": "concept", "title": "readability"}], "description": "Students edit for readers who need quick comprehension, including readers on mobile devices and readers encountering unfamiliar subjects."}, {"id": "6eb8361a-ae6b-4414-ac8e-4ebdeefb034a", "type": "subtopic", "title": "Protecting voice", "children": [{"id": "e094a65d-1631-4d09-9ae9-7f2393611bb5", "type": "concept", "title": "rhythm"}, {"id": "206b9892-8c46-422e-8045-37a43ed712b5", "type": "concept", "title": "tone"}, {"id": "c484ed41-7e1f-4663-a847-ed35c5740dd9", "type": "concept", "title": "reporter style"}], "description": "The class distinguishes productive sharpening from overediting that makes every story sound the same."}]}, {"id": "09283749-41ec-44e7-9f62-45254b532143", "type": "topic", "title": "Story Structure and Line Editing", "description": "Editors do more than fix sentences: they help stories find the right architecture so readers understand why the story matters and how each part connects.", "children": [{"id": "e3886773-fb8b-4001-be2d-51b412e783e0", "type": "subtopic", "title": "Leads and nut grafs", "children": [{"id": "64be1dfb-93b0-46a3-bc60-b6de872e496b", "type": "concept", "title": "hard-news leads"}, {"id": "675ca267-683d-44f7-830a-989c45ba0a25", "type": "concept", "title": "delayed leads"}, {"id": "5003037a-23bf-4658-90bc-4cce60ebbd36", "type": "concept", "title": "nut graf placement"}], "description": "Students evaluate whether openings establish news, stakes, context, and reader orientation quickly enough."}, {"id": "6946341a-e9fe-41b1-ae37-109b31c35596", "type": "subtopic", "title": "Story spine and ordering", "children": [{"id": "1926110a-3ce4-4bc9-8cb0-214ef3e63cf8", "type": "concept", "title": "story maps"}, {"id": "1386946d-e5cc-449b-92b8-901332fbdf73", "type": "concept", "title": "chronology versus theme"}, {"id": "4b1d2954-cb45-4f0f-bb2d-e02272cf29c5", "type": "concept", "title": "section transitions"}], "description": "The unit teaches editors to map a draft's logic and reorder material when the strongest path is hidden."}, {"id": "57b600fc-2a24-4690-a5b5-d083a4969729", "type": "subtopic", "title": "Evidence and quote placement", "children": [{"id": "2ca1ab62-8507-4fc7-a588-1762b15eaa93", "type": "concept", "title": "claim-evidence alignment"}, {"id": "fbe3d33f-81c1-44c8-9e89-465a90f80d36", "type": "concept", "title": "quote selection"}, {"id": "793aaafc-58cb-44bf-8731-78d55edc5d12", "type": "concept", "title": "paraphrase balance"}], "description": "Students learn how to place evidence where it earns claims and how to avoid quote dumps."}, {"id": "95bbfd7d-e236-40b5-9c93-7d6df31a05ce", "type": "subtopic", "title": "Endings and reader takeaways", "children": [{"id": "505af2e3-8c61-444e-bd4a-37a3b5e9c908", "type": "concept", "title": "kickers"}, {"id": "a35be7aa-e884-4677-aabb-31160a835b69", "type": "concept", "title": "future implications"}, {"id": "f3598f35-2f39-48bc-8630-e78511091689", "type": "concept", "title": "closing context"}], "description": "Editors practice closing stories with consequence, forward motion, or resonance rather than abrupt stop signs."}]}, {"id": "a640a309-975f-4919-bc63-d235d9f26a03", "type": "topic", "title": "Headlines, SEO, and Digital Display", "description": "Headlines are journalism's front door. Students learn to write display copy that is accurate, specific, searchable, and strong enough to earn attention ethically.", "children": [{"id": "20684eb9-1c54-4f73-9b7d-a76800b2806a", "type": "subtopic", "title": "Print and digital headline forms", "children": [{"id": "4e2e0215-707d-42cb-8a81-65676dc1babc", "type": "concept", "title": "main headlines"}, {"id": "bdf3de1d-813f-43db-a257-36c3bfdcf541", "type": "concept", "title": "decks"}, {"id": "8a3efb61-01fd-4a4f-bb6d-ec84147efb40", "type": "concept", "title": "alerts"}], "description": "Students compare main heads, decks, labels, newsletter subject lines, push alerts, and social display text."}, {"id": "7420d121-2d56-45d6-b3e6-f78517f12b5a", "type": "subtopic", "title": "SEO fundamentals for editors", "children": [{"id": "8d98c056-11e7-4128-bb9a-f518d455eaca", "type": "concept", "title": "search terms"}, {"id": "84d0d3fd-6344-444f-99c9-bf5207dd6830", "type": "concept", "title": "metadata"}, {"id": "0508a96f-8df4-44b9-b102-020a087cb375", "type": "concept", "title": "slug strategy"}], "description": "The unit shows how search intent, keywords, URLs, metadata, and headline clarity help readers find journalism without clickbait."}, {"id": "ab86a0f6-2f6b-4a4b-9d39-6a161ae39cfe", "type": "subtopic", "title": "Accuracy and fairness in display type", "children": [{"id": "1983e297-7e5f-4852-934d-eb65da61c899", "type": "concept", "title": "attribution in heads"}, {"id": "dedd1011-7f4b-45aa-beed-018ca9334c22", "type": "concept", "title": "causal claims"}, {"id": "f44256c6-3eb7-4a16-8004-b6584dd62a66", "type": "concept", "title": "tone risk"}], "description": "Students learn why a headline must not overstate, imply causation, erase attribution, or sensationalize harm."}, {"id": "cb7a7f49-ab67-4df2-b18a-da823dd1d9cd", "type": "subtopic", "title": "A/B testing and audience feedback", "children": [{"id": "fe9539b0-df87-4935-abd4-0014c4248801", "type": "concept", "title": "click-through rate"}, {"id": "3685e2d2-efaf-409b-8263-19f62fa99a25", "type": "concept", "title": "engaged time"}, {"id": "7a8ffd09-ac2a-4652-a034-88a42e49ed13", "type": "concept", "title": "headline variants"}], "description": "Editors learn how analytics can improve headline craft when used in service of public-interest journalism."}]}, {"id": "a585a4b3-be42-4922-8a0f-6c53af9c60f7", "type": "topic", "title": "Cutlines, Captions, and Visual Editing", "description": "Visual journalism needs the same rigor as text. This unit trains students to edit images and captions for accuracy, context, dignity, and story value.", "children": [{"id": "23298f90-210f-48fa-bffd-d740325669a3", "type": "subtopic", "title": "Caption fundamentals", "children": [{"id": "d19c045c-0304-418a-a0c5-e2d66c0f41d5", "type": "concept", "title": "present-tense captions"}, {"id": "ffe02c24-c72e-4293-af58-0912c4f14095", "type": "concept", "title": "photo credits"}, {"id": "ab15da65-cb8b-4ab9-a843-aa6de3140ca1", "type": "concept", "title": "context sentences"}], "description": "Students practice identifying who, what, where, when, and why in captions while avoiding obvious or unsupported claims."}, {"id": "789bc0d4-a0fc-4520-a266-a28f32f22756", "type": "subtopic", "title": "Photo selection and sequencing", "children": [{"id": "4cd60582-b2d6-4670-a2ff-cf733446813a", "type": "concept", "title": "news value"}, {"id": "ff4acef0-0fbc-4b78-b70c-24131a2f2134", "type": "concept", "title": "visual variety"}, {"id": "228cf5dc-af41-42fd-b50a-4068ffba56d1", "type": "concept", "title": "sequence logic"}], "description": "Editors learn how image choice affects emphasis, fairness, emotion, and reader interpretation."}, {"id": "0994ddbb-059d-4160-a1fe-73bc5ac9bbbf", "type": "subtopic", "title": "Ethics of image editing", "children": [{"id": "eaed050c-b5e6-43cc-831b-64eedf5831a7", "type": "concept", "title": "cropping ethics"}, {"id": "07702f39-8002-4bb5-a2e2-4182c6b8139f", "type": "concept", "title": "graphic content"}, {"id": "7153667c-59d9-41aa-be94-0944a71ada55", "type": "concept", "title": "representation"}], "description": "The class discusses manipulation, cropping, graphic images, consent, stereotypes, and harm minimization."}, {"id": "c291162d-32ac-48d2-bbc5-e43b836c915d", "type": "subtopic", "title": "Accessibility and alternative text", "children": [{"id": "e86a0898-0f47-4b33-9b86-428a9e0342fe", "type": "concept", "title": "alt text"}, {"id": "d35850aa-1eef-4830-bc86-d3ba74425e8d", "type": "concept", "title": "decorative images"}, {"id": "2c0b9b03-7865-4e3a-9330-3be048bf5b4d", "type": "concept", "title": "screen reader context"}], "description": "Students write alt text and visual descriptions that make image information available beyond sighted readers."}]}, {"id": "fd7f1a05-2ad0-41ed-ae01-f2167eb77552", "type": "topic", "title": "Legal, Ethical, and Standards Review", "description": "Editors are a crucial line of defense for both public trust and institutional risk. This unit connects legal literacy with ethical reasoning.", "children": [{"id": "f67203c0-ae00-40ee-8cf5-0da26c014039", "type": "subtopic", "title": "Libel, privacy, and defamation risk", "children": [{"id": "21f9c215-9b22-4a7b-b06a-030328096e62", "type": "concept", "title": "defamation elements"}, {"id": "98b85c13-e462-46cd-80d4-f7d3034eb3e4", "type": "concept", "title": "public versus private figures"}, {"id": "7341080f-b8d4-4a9c-9869-ac6564cf37f0", "type": "concept", "title": "right of reply"}], "description": "Students learn to spot unsupported damaging claims, loaded wording, identification risk, and missing opportunity to respond."}, {"id": "bbdcf948-b3d7-4b0e-8be8-e873c2bcfeff", "type": "subtopic", "title": "Attribution, plagiarism, and originality", "children": [{"id": "4e33a69b-44b0-46c6-bef7-a9f613ebe594", "type": "concept", "title": "citation habits"}, {"id": "efca2c18-d4ed-4907-b67e-7dcbf0119c02", "type": "concept", "title": "patchwriting"}, {"id": "031eb590-dd89-402a-811c-03443c7e8ed6", "type": "concept", "title": "linking and credit"}], "description": "The unit covers source credit, lifted language, aggregation ethics, and how to rewrite without stealing."}, {"id": "31ac2e1f-7213-40df-a77d-203e39d3a5ce", "type": "subtopic", "title": "Conflicts, independence, and transparency", "children": [{"id": "fb5e9168-8dde-4af3-8e55-7e018e571c8d", "type": "concept", "title": "anonymous sourcing"}, {"id": "86cebe40-75da-4401-8fa3-2c507b8dab17", "type": "concept", "title": "disclosures"}, {"id": "a2bf00c2-b641-43d4-bd0d-7e3b73245387", "type": "concept", "title": "editor's notes"}], "description": "Students evaluate conflicts of interest, sponsorship, corrections, anonymous sources, and disclosure language."}, {"id": "e207b188-6161-45b1-bd9c-e3af8d6d66af", "type": "subtopic", "title": "Standards review checklists", "children": [{"id": "aaca4405-d81d-445a-89e2-b9d9bc800f54", "type": "concept", "title": "risk flags"}, {"id": "696fe538-6221-42ba-920e-854585380dd6", "type": "concept", "title": "standards escalation"}, {"id": "a5becda3-3204-4efa-ba9b-d32590349779", "type": "concept", "title": "prepublication review"}], "description": "The class builds publication-ready checklists for high-risk stories, investigations, minors, trauma, and sensitive allegations."}]}, {"id": "b5a2be5b-abc9-444a-bb69-2f7e3cfad3d0", "type": "topic", "title": "Inclusive, Precise, and Sensitive Language", "description": "World-class editing requires language judgment that is accurate, current, specific, and humane. Students learn to edit identity-related language with care and evidence.", "children": [{"id": "97a0662d-b966-4f67-851d-3c377b9c929b", "type": "subtopic", "title": "Identity, race, ethnicity, gender, and disability", "children": [{"id": "137f4f44-1704-4eb3-a96a-18e7fee3ad27", "type": "concept", "title": "self-identification"}, {"id": "dfd6e68d-4fc0-4890-b3f7-3d5437e53ca4", "type": "concept", "title": "person-first and identity-first language"}, {"id": "52426611-4a7a-4eb1-b449-fefd16e35a28", "type": "concept", "title": "relevance tests"}], "description": "Students practice asking whether identity is relevant, how people describe themselves, and which terms avoid stereotype or erasure."}, {"id": "c04c1d71-d6d2-4add-9aa5-dc763adc5ca0", "type": "subtopic", "title": "Trauma-informed editing", "children": [{"id": "6ba92dfc-f65f-4dd7-b344-344998df5d85", "type": "concept", "title": "survivor language"}, {"id": "bf84c906-6439-4a6e-976d-e676cc7c5178", "type": "concept", "title": "graphic detail"}, {"id": "e8a8cb06-d3d0-463d-85f3-54c5d84a9c8b", "type": "concept", "title": "minors and vulnerable sources"}], "description": "The unit shows how word choice can reduce harm while preserving truth and accountability."}, {"id": "626bf1dc-3883-4e02-acd4-4baf5388f095", "type": "subtopic", "title": "Precision over euphemism", "children": [{"id": "ebc48c95-aa7e-4708-95e8-6ae1013549a1", "type": "concept", "title": "agency"}, {"id": "e8c6a776-3094-4134-9f95-77c389059158", "type": "concept", "title": "loaded verbs"}, {"id": "f5aea231-1b37-43d8-bd35-1802f85f7938", "type": "concept", "title": "specific descriptors"}], "description": "Students learn to avoid both stigmatizing language and vague language that hides responsibility."}, {"id": "219636f7-d3af-4a34-8e7d-c78e96368c4c", "type": "subtopic", "title": "Updating style guidance", "children": [{"id": "f453b3fb-16f3-413a-b30f-a8f31a7fa34b", "type": "concept", "title": "style updates"}, {"id": "0bca477a-5004-4041-a817-115c1961583e", "type": "concept", "title": "consultation"}, {"id": "59f95288-f7b3-41b8-b303-666185aecd89", "type": "concept", "title": "house guide memos"}], "description": "Editors learn how to monitor evolving language guidance and document local decisions transparently."}]}, {"id": "e587ac6e-a073-4be8-97d3-4082bed5041f", "type": "topic", "title": "Working with Reporters, Writers, and Newsroom Teams", "description": "Editing is collaborative leadership. Students learn how to improve copy, coach writers, and keep publication moving without turning edits into a power struggle.", "children": [{"id": "eb6e5306-ac2c-4059-a101-9713f88ec024", "type": "subtopic", "title": "Editor-writer communication", "children": [{"id": "74eec118-3022-493d-8788-871c1d82e351", "type": "concept", "title": "query etiquette"}, {"id": "f1a68c20-a5b2-48f3-9ee0-d47d35e8c5e9", "type": "concept", "title": "edit rationales"}, {"id": "f639268e-729d-4cc1-89bc-e53a05ecf4f9", "type": "concept", "title": "author ownership"}], "description": "Students practice clear queries, useful margin notes, and respectful conversations about major revisions."}, {"id": "051bb4b4-1e3d-416f-9df2-1ab2c90975d6", "type": "subtopic", "title": "Coaching and developmental feedback", "children": [{"id": "d535bc8c-41f6-4901-a709-fd146a9dd544", "type": "concept", "title": "pattern notes"}, {"id": "4d5172b5-3949-484e-8293-06bb7318c496", "type": "concept", "title": "prioritized feedback"}, {"id": "ec4a6692-5b2c-4680-a273-cf8885f2a0a0", "type": "concept", "title": "next-draft goals"}], "description": "The unit treats editing as a teaching practice that helps reporters improve over time."}, {"id": "bcc44495-ac9a-4e0b-8203-4d5d85d05521", "type": "subtopic", "title": "Deadline decision-making", "children": [{"id": "f3bccb38-fc10-4cb0-bd2c-0eb77cc454e1", "type": "concept", "title": "must-fix versus nice-to-fix"}, {"id": "f32d03a2-7eb5-4d69-89be-411e4a4c635b", "type": "concept", "title": "risk triage"}, {"id": "80250a21-ef19-4cab-88a8-b2ecae07f610", "type": "concept", "title": "publication readiness"}], "description": "Students learn how editors triage problems when time is short."}, {"id": "3ddf228b-433a-4749-8353-86b3e2d564a7", "type": "subtopic", "title": "Newsroom collaboration", "children": [{"id": "575011e2-54f5-49cc-b48d-43ac7542d267", "type": "concept", "title": "handoffs"}, {"id": "71d63545-d355-42ea-b04c-a84a651ba0a8", "type": "concept", "title": "copy flow"}, {"id": "fb01e7e9-bb0e-41e0-aa5a-3403f7be9221", "type": "concept", "title": "cross-desk coordination"}], "description": "Editors coordinate with visuals, audience, legal, product, social, and production teams on story packages."}]}, {"id": "40efbfca-aa2b-4687-93a6-9865357f1ff2", "type": "topic", "title": "Print, Digital, and CMS Production", "description": "A story is not finished when the sentences are clean. Production editing ensures the published package functions correctly wherever readers encounter it.", "children": [{"id": "0254fef2-5204-4af3-aec1-deeca8ae648e", "type": "subtopic", "title": "CMS preparation", "children": [{"id": "557eadda-a552-4050-959e-bd91a81547eb", "type": "concept", "title": "slugs"}, {"id": "403ab8a2-8389-4cae-adf0-b4f92838afdb", "type": "concept", "title": "tags"}, {"id": "caa68b8b-e9e3-4e1c-a688-9943a38e5fe8", "type": "concept", "title": "embeds"}], "description": "Students learn to check URLs, embeds, tags, authorship, related links, timestamps, metadata, and preview states."}, {"id": "1bb06554-fa14-486c-98ec-de775088a133", "type": "subtopic", "title": "Print page proofing", "children": [{"id": "e99a9150-c073-4cee-b44e-45c6a9364e0c", "type": "concept", "title": "page proofs"}, {"id": "ea49a23f-90ee-4f7b-897e-65c6e8bcc979", "type": "concept", "title": "continuation lines"}, {"id": "cdd50830-84a6-43b7-aacf-1ef1cf2a60af", "type": "concept", "title": "display hierarchy"}], "description": "The unit covers jumps, widows, orphans, folios, captions, display type, page hierarchy, and final proof marks."}, {"id": "501be346-a51b-41e0-b049-128048ee89c6", "type": "subtopic", "title": "Newsletter and social packaging", "children": [{"id": "d0a7ed34-eb5d-4079-9e31-1433923939d0", "type": "concept", "title": "subject lines"}, {"id": "3a7ad865-218e-4575-b40f-134583d5d34f", "type": "concept", "title": "social captions"}, {"id": "4408a60d-52a5-44af-a671-609fb0975f37", "type": "concept", "title": "push alerts"}], "description": "Editors adapt copy for email, social cards, push alerts, and platform-specific reader expectations."}, {"id": "901e3dfe-9877-4086-96c3-2218ec2ea655", "type": "subtopic", "title": "Quality assurance before publication", "children": [{"id": "511d95f8-2911-4f15-b672-70b97fdbccfc", "type": "concept", "title": "link checks"}, {"id": "4a3656c0-8de2-4494-a8e2-f6e648ec3c48", "type": "concept", "title": "mobile preview"}, {"id": "2b61876a-1a4a-436c-926c-464db651f467", "type": "concept", "title": "archive metadata"}], "description": "Students run final checks across desktop, mobile, print, newsletters, and archives."}]}, {"id": "9dcae7f0-b68e-4585-a29d-a3abb9fbdc5d", "type": "topic", "title": "Editing Multimedia, Audio, Video, and Data Stories", "description": "Modern editors must evaluate more than text. This unit extends editing judgment to audio scripts, video captions, interactive elements, graphics, and data-driven work.", "children": [{"id": "5c2892d1-9dd5-40cc-a863-3a18cd873eeb", "type": "subtopic", "title": "Audio and broadcast scripts", "children": [{"id": "37e3693a-ff23-46b7-afa5-e31e75c0234a", "type": "concept", "title": "read-aloud edits"}, {"id": "6c41d166-22ed-4f3d-be5c-85c3cc67795a", "type": "concept", "title": "host intros"}, {"id": "a7c7584c-8a18-435b-b319-921a383272f8", "type": "concept", "title": "soundbite context"}], "description": "Students edit scripts for the ear, timing, attribution, sound cues, and conversational clarity."}, {"id": "7053dca3-3d46-4aa3-99bd-19140850df4e", "type": "subtopic", "title": "Video and transcript editing", "children": [{"id": "374c9df4-6ba8-41cc-9a19-a055a8242506", "type": "concept", "title": "captions"}, {"id": "b4360293-6e62-4dde-91a9-ba7cbaecc7b9", "type": "concept", "title": "lower thirds"}, {"id": "bbbe9f1d-b7bd-4038-8b05-57db5ddcc9c7", "type": "concept", "title": "sequence continuity"}], "description": "The unit covers lower thirds, subtitles, transcript accuracy, sequence logic, and ethical edits."}, {"id": "87931222-3fde-4b0b-9876-ae7cca6538be", "type": "subtopic", "title": "Graphics and data displays", "children": [{"id": "4314e124-7f5c-4fd8-adc6-686cb7bd5385", "type": "concept", "title": "chart integrity"}, {"id": "0a49e06f-94ae-417b-a81d-5c0c6da239eb", "type": "concept", "title": "source notes"}, {"id": "3aa82552-be35-495f-9a21-40a82da2a8d9", "type": "concept", "title": "annotation"}], "description": "Editors learn to check chart titles, labels, sourcing, units, uncertainty, and whether the graphic supports the claim."}, {"id": "887edffd-dfd8-4117-b50c-9b8da536e071", "type": "subtopic", "title": "Interactive and mobile-first packages", "children": [{"id": "95b58d48-fb81-438f-81ee-82d8f0d9bdef", "type": "concept", "title": "interaction cues"}, {"id": "e9a03b93-bee1-492e-9ad9-26c58148c92c", "type": "concept", "title": "mobile layout"}, {"id": "05a79aae-0696-4e7a-833e-ccc130296e94", "type": "concept", "title": "fallback text"}], "description": "Students evaluate scrollytelling, maps, timelines, and interactive elements for usability and accuracy."}]}, {"id": "0e657615-e437-4ef2-a92e-f931a71e954f", "type": "topic", "title": "Editing Tools, Automation, and Responsible AI", "description": "Editing tools can improve speed and consistency, but editors remain accountable for judgment. This unit teaches students to use automation critically.", "children": [{"id": "6524c711-68da-46bd-99ae-7f50bae01578", "type": "subtopic", "title": "Digital editing tools", "children": [{"id": "cd11c1bf-48fc-41f9-9518-bda9007003d5", "type": "concept", "title": "style checkers"}, {"id": "4a7270f0-8dc4-475f-bb88-13683e92ea81", "type": "concept", "title": "collaborative docs"}, {"id": "29a9e18b-6e85-49e4-9472-6a4995142e1d", "type": "concept", "title": "CMS validators"}], "description": "Students compare grammar checkers, style linters, collaborative editing tools, CMS checks, and newsroom templates."}, {"id": "9abe066a-77dc-4c4b-9051-6dddf2168f73", "type": "subtopic", "title": "AI-assisted editing boundaries", "children": [{"id": "0fbd59d7-55ec-41fc-83ec-12fbb4c5d454", "type": "concept", "title": "hallucination checks"}, {"id": "c5a4222f-ad52-4747-80bb-8e7b59118895", "type": "concept", "title": "confidentiality"}, {"id": "14973b36-5647-48e7-9c04-c85998903ea3", "type": "concept", "title": "human approval"}], "description": "The class examines where AI may help with drafts, summaries, consistency checks, and headline variants, and where it can introduce risk."}, {"id": "bdbe2285-9f20-49de-a6a5-e89ae22a3f7c", "type": "subtopic", "title": "Bias and accountability in automation", "children": [{"id": "4e6d4684-9b91-4b20-b3f0-2f262d7a9c7a", "type": "concept", "title": "bias review"}, {"id": "1e13859a-1dd3-42c2-9951-d82df295036f", "type": "concept", "title": "meaning preservation"}, {"id": "567b52d3-97d8-4ea6-b82f-5c6c4b4bb82c", "type": "concept", "title": "audit trails"}], "description": "Students learn to question automated suggestions that flatten voice, change meaning, or encode bias."}, {"id": "08aa0050-5a6b-4a1d-a621-3951fa3860c6", "type": "subtopic", "title": "Tool policies and disclosure", "children": [{"id": "2b0197a3-9247-490d-988b-9b0f218438f1", "type": "concept", "title": "policy language"}, {"id": "4c03c042-0f5a-479f-84c5-314600ca6306", "type": "concept", "title": "data security"}, {"id": "a1e980fc-e220-4c2c-9b3e-a55a5bca4f56", "type": "concept", "title": "approval workflows"}], "description": "Editors draft newsroom rules for tool use, source protection, verification, and disclosure."}]}, {"id": "ce7edf8a-dbd1-4e84-868e-6ec14b6a4fad", "type": "topic", "title": "Capstone Copy Desk Simulation", "description": "The capstone turns the course into a working desk. Students edit a complete story package under deadline and defend their decisions.", "children": [{"id": "bacb9eae-09f0-4383-b0bd-1ff54dec1e29", "type": "subtopic", "title": "Editing a live-style story package", "children": [{"id": "76a11ab6-20bb-4fd8-8d13-483dfb36ad05", "type": "concept", "title": "story package checklist"}, {"id": "539c15af-4630-404a-bf00-06af426e6d30", "type": "concept", "title": "desk workflow"}, {"id": "b9a55c44-85ae-40d2-9be2-866d50f15e81", "type": "concept", "title": "final proof"}], "description": "Students handle text, headlines, captions, metadata, links, visual elements, and publication checks as one coherent package."}, {"id": "79f17894-8010-42a3-be48-d9b4cf314e68", "type": "subtopic", "title": "Standards memo and edit rationale", "children": [{"id": "a8e5b421-5efa-472c-b33c-4588e216ddc6", "type": "concept", "title": "edit memo"}, {"id": "2b6ec23c-28c1-4c94-a301-a252fc74dc7c", "type": "concept", "title": "risk notes"}, {"id": "74e18284-209f-4d37-85df-3a06fc655ab3", "type": "concept", "title": "source questions"}], "description": "Students explain major edits, unresolved risks, verification steps, and publication recommendations."}, {"id": "f4659e5b-ab61-4db9-9803-e85ac89c63b1", "type": "subtopic", "title": "Peer desk review", "children": [{"id": "0932ac4c-40db-45d5-99c9-cd47b8353926", "type": "concept", "title": "second reads"}, {"id": "4aa19fde-d413-4ba0-9590-c49dbbf2c4fa", "type": "concept", "title": "quality rubric"}, {"id": "5c50aac4-9fdc-4acd-8829-0cbf7bfbf5d8", "type": "concept", "title": "reader impact"}], "description": "The class uses structured peer review to test whether edits improved accuracy, clarity, fairness, and usability."}, {"id": "e7ffe5a9-408e-4a35-8465-a292ca952c92", "type": "subtopic", "title": "Portfolio reflection", "children": [{"id": "a826fa4f-a4c6-4c81-8c02-270faf2acd49", "type": "concept", "title": "before/after samples"}, {"id": "0db80075-ef45-4cf6-87a7-0fd05d1cc43d", "type": "concept", "title": "self-assessment"}, {"id": "df3ac9c3-a320-46dd-9e1b-2ae286321dea", "type": "concept", "title": "professional portfolio"}], "description": "Students assemble before-and-after edits showing growth in judgment, craft, collaboration, and standards."}]}], "dbBacked": true}$edcojson$::jsonb,
