  ('c82c2ad6-a588-4f1e-ba71-0eaa88b5f455', 'b8c9d0e1-2f3a-4b14-9c34-4d5e6f7a8b54', null, 'topic'::public.curated_course_node_type, 'The Editing Process and Editorial Judgment', 'This opening unit frames editing as a disciplined act of judgment: protecting the reader, strengthening the story, and improving the work without erasing the reporter''s voice.', 0),
