  ('2ed39aab-8657-450a-bd09-d52e809f88b4', 'b8c9d0e1-2f3a-4b14-9c34-4d5e6f7a8b54', '1ab7590e-1ad6-4d98-af86-ea5f0b5ea47b', 'concept'::public.curated_course_node_type, 'editor''s notes', null, 2),
  ('b7b54da0-d491-47f7-807f-c3a8ef30db30', 'b8c9d0e1-2f3a-4b14-9c34-4d5e6f7a8b54', null, 'topic'::public.curated_course_node_type, 'Editing for Clarity, Concision, and Voice', 'This unit teaches students to make stories sharper without flattening them. The goal is prose that moves quickly, says exactly what it means, and still sounds human.', 3),
