  ('0d227856-38a6-4871-a8ea-676552b25928', 'b8c9d0e1-2f3a-4b14-9c34-4d5e6f7a8b54', 'aac2e328-2ef1-435c-ad07-bfd8dafbe80f', 'concept'::public.curated_course_node_type, 'readability', null, 2),
